"""The pieces every rendered page shares: the generated header, tables, numbers and set groups."""

from collections.abc import Mapping, Sequence
from typing import cast

from coach.core.config import Units

HEADER = (
    "> Generated by `coach publish` from the store; hand edits are overwritten at the next publish."
)
ENGINE_REPO = "https://github.com/joeuk89/strength-coach"
MANUAL_CLIMB = "when you and the coach agree"


def page(title: str, *sections: str) -> str:
    """The header, the title and each non-empty section, ending in one newline; a section's own
    text is kept as it is, so a read stays verbatim."""
    parts = [HEADER, f"# {title}", *(s for s in sections if s.strip())]
    return "\n\n".join(parts).rstrip("\n") + "\n"


def section(heading: str, body: str) -> str:
    return f"## {heading}\n\n{body}" if body.strip() else ""


def table(headings: Sequence[str], rows: Sequence[Sequence[object]]) -> str:
    if not rows:
        return ""
    lines = [
        "| " + " | ".join(headings) + " |",
        "| " + " | ".join("---" for _ in headings) + " |",
        *("| " + " | ".join(cell(value) for value in row) + " |" for row in rows),
    ]
    return "\n".join(lines)


def bullets(items: Sequence[str]) -> str:
    return "\n".join(f"- {item}" for item in items)


def cell(value: object) -> str:
    """A table cell: numbers as stored, nothing as a dash, pipes escaped."""
    if value is None:
        return "–"
    if isinstance(value, bool):
        return "yes" if value else "no"
    if isinstance(value, int | float):
        return number(value)
    if isinstance(value, list | tuple):
        return ", ".join(cell(v) for v in cast(Sequence[object], value)) or "none"
    if isinstance(value, Mapping):
        pairs = cast(Mapping[str, object], value).items()
        return ", ".join(f"{k} {cell(v)}" for k, v in pairs)
    return str(value).replace("|", "\\|").replace("\n", " ")


def number(value: float) -> str:
    """The stored value, without a trailing `.0`."""
    if isinstance(value, float) and value.is_integer():
        return str(int(value))
    return str(value)


def group_text(group: Mapping[str, object], units: Units) -> str:
    """`4×6–8 @8 at 175 lb`; a warm-up says so."""
    count = group.get("count")
    rep_range = group.get("range")
    if isinstance(rep_range, list):
        low, high = cast(list[int], rep_range)
        shape = f"{count}×{low}–{high}"
    elif group.get("reps") is not None:
        shape = f"{count}×{group['reps']}"
    else:
        shape = f"{count}×{group.get('duration_s')} s"
    rpe = group.get("rpe")
    if isinstance(rpe, int | float):
        shape += f" @{number(rpe)}"
    cap = group.get("rpe_cap")
    if isinstance(cap, int | float):
        shape += f" (stop at RPE {number(cap)})"
    load = group.get("load")
    if isinstance(load, int | float):
        shape += f" at {number(load)} {units}"
    return f"warm-up {shape}" if group.get("type") == "warm_up" else shape


def rn_link(rn: str, pin: str) -> str:
    """The note a flag cites, at the pinned engine tag (validation.md, "One Flag shape
    everywhere")."""
    note = rn.removeprefix("rn:").split(" §")[0].split(".")[0]
    return f"[{rn}]({ENGINE_REPO}/blob/v{pin}/docs/spec/{note}.md)"


def flag_text(flag: Mapping[str, object], pin: str) -> str:
    text = f"{flag.get('severity')} `{flag.get('code')}`: {flag.get('message')}"
    rn = flag.get("rn")
    return f"{text} ({rn_link(rn, pin)})" if isinstance(rn, str) else text
